            if next_ ~= currentTask then
                currentTask = next_
                log(S(341) .. (currentTask and currentTask.name or S(548)))
            end
            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            run(currentTask)
        end
    end)
end
function scheduler.Stop()
    if connection then
        connection:Disconnect()
        connection = nil
    end
    currentTask = nil
end
return scheduler
end
