            if info and (info.count == nil or info.count > 0) then
                info.slot = slot
                local key = info.name .. S(476) .. slot
                if not reported[key] then
                    reported[key] = true
                    log(S(184) .. slot .. S(364) .. info.name
                        .. S(560) .. info.power .. S(40) .. tostring(info.count))
                end
                table.insert(slots, info)
            end
        end
    end
    table.sort(slots, function(a, b)
        return a.power > b.power
    end)
    return slots
end
return getMinerSlots
end
end
